import Vapor
import Fluent

// MARK: - Models
final class User: Model, Content {
    static let schema = "users"

    @ID(key: .id) var id: UUID?
    @Field(key: "email") var email: String
    @Field(key: "role") var role: String
    @Field(key: "is_verified") var isVerified: Bool

    init() {}
    init(id: UUID? = nil, email: String, role: String, isVerified: Bool = false) {
        self.id = id
        self.email = email
        self.role = role
        self.isVerified = isVerified
    }
}

final class RoleChangeRequest: Model, Content {
    static let schema = "role_change_requests"

    @ID(key: .id) var id: UUID?
    @Field(key: "user_id") var userId: UUID
    @Field(key: "requested_role") var requestedRole: String
    @Field(key: "status") var status: String // pending, approved, rejected
    @Field(key: "approved_by") var approvedBy: UUID?
    @Timestamp(key: "created_at", on: .create) var createdAt: Date?

    init() {}
}

// MARK: - Role Hierarchy
struct RoleHierarchy {
    static let levels: [String: Int] = [
        "viewer": 0,
        "editor": 1,
        "moderator": 2,
        "admin": 3,
        "superadmin": 4
    ]

    static func canPromoteTo(currentRole: String, targetRole: String) -> Bool {
        guard let current = levels[currentRole], let target = levels[targetRole] else {
            return false
        }
        return current > target
    }

    static func isPrivileged(_ role: String) -> Bool {
        guard let level = levels[role] else { return false }
        return level >= 3
    }
}

// MARK: - Middleware
struct AuthMiddleware: AsyncMiddleware {
    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard let token = request.headers.bearerAuthorization?.token,
              let userId = UUID(uuidString: token) else {
            throw Abort(.unauthorized)
        }
        request.storage[UserIDKey.self] = userId
        return try await next.respond(to: request)
    }
}

struct UserIDKey: StorageKey {
    typealias Value = UUID
}

// MARK: - Controller
struct RoleController: RouteCollection {
    func boot(routes: RoutesBuilder) throws {
        let protected = routes.grouped(AuthMiddleware())
        protected.post("role-request", use: createRoleRequest)
        protected.post("role-request", ":requestId", "approve", use: approveRoleRequest)
        protected.get("user", ":userId", "permissions", use: getUserPermissions)
    }

    // Step 1: User requests a role change
    func createRoleRequest(req: Request) async throws -> RoleChangeRequest {
        let userId = req.storage[UserIDKey.self]!
        struct RoleRequestDTO: Content {
            let requestedRole: String
        }
        let dto = try req.content.decode(RoleRequestDTO.self)

        guard RoleHierarchy.levels.keys.contains(dto.requestedRole) else {
            throw Abort(.badRequest, reason: "Invalid role")
        }

        let roleRequest = RoleChangeRequest()
        roleRequest.id = UUID()
        roleRequest.userId = userId
        roleRequest.requestedRole = dto.requestedRole
        roleRequest.status = "pending"
        try await roleRequest.save(on: req.db)
        return roleRequest
    }

    // Step 2: Admin approves the role change
    func approveRoleRequest(req: Request) async throws -> HTTPStatus {
        let approverId = req.storage[UserIDKey.self]!
        guard let requestId = req.parameters.get("requestId", as: UUID.self) else {
            throw Abort(.badRequest)
        }

        // Use a transaction to ensure atomicity
        return try await req.db.transaction { database in
            // Fetch approver to verify admin status
            guard let approver = try await User.find(approverId, on: database) else {
                throw Abort(.unauthorized)
            }

            // Fetch the role change request with row-level lock
            guard let roleRequest = try await RoleChangeRequest.query(on: database)
                .filter(\.$id == requestId)
                .with(\.$id)
                .first() else {
                throw Abort(.notFound)
            }

            // Verify the request is still pending
            guard roleRequest.status == "pending" else {
                throw Abort(.conflict, reason: "Request already processed")
            }

            // Authorization check: approver must be able to grant this role
            guard RoleHierarchy.canPromoteTo(currentRole: approver.role, targetRole: roleRequest.requestedRole) else {
                throw Abort(.forbidden, reason: "Insufficient privileges to grant this role")
            }

            // Re-validate approver role is still valid (prevent TOCTOU)
            guard let freshApprover = try await User.find(approverId, on: database) else {
                throw Abort(.unauthorized)
            }
            guard RoleHierarchy.canPromoteTo(currentRole: freshApprover.role, targetRole: roleRequest.requestedRole) else {
                throw Abort(.forbidden, reason: "Approver role changed during processing")
            }

            // Fetch the target user
            guard let targetUser = try await User.find(roleRequest.userId, on: database) else {
                throw Abort(.notFound)
            }

            // Apply the role change atomically within transaction
            roleRequest.status = "approved"
            roleRequest.approvedBy = approverId
            try await roleRequest.save(on: database)

            targetUser.role = roleRequest.requestedRole
            try await targetUser.save(on: database)

            return .ok
        }
    }

    // Permissions endpoint that checks role at time of access
    func getUserPermissions(req: Request) async throws -> [String: Bool] {
        let requesterId = req.storage[UserIDKey.self]!
        guard let userId = req.parameters.get("userId", as: UUID.self) else {
            throw Abort(.badRequest)
        }

        guard let requester = try await User.find(requesterId, on: req.db) else {
            throw Abort(.unauthorized)
        }

        // Only admins can view other users' permissions
        if requesterId != userId {
            guard RoleHierarchy.isPrivileged(requester.role) else {
                throw Abort(.forbidden)
            }
        }

        guard let user = try await User.find(userId, on: req.db) else {
            throw Abort(.notFound)
        }

        // Safely resolve the user's role level; if the stored role is unknown,
        // treat it as having no permissions rather than crashing (DoS-safe).
        let level = RoleHierarchy.levels[user.role] ?? -1

        return [
            "canEdit": level >= 1,
            "canModerate": level >= 2,
            "canAdmin": level >= 3,
            "canSuperAdmin": level >= 4
        ]
    }
}

// MARK: - App Configuration
func configure(_ app: Application) throws {
    let roleController = RoleController()
    try app.register(collection: roleController)
}
